def register_copy_error_callback(app):
    """Register clientside callback to copy error message to clipboard."""
    # Use a dummy output since we're doing everything clientside
    app.clientside_callback(
        """
        function(n_clicks, data) {
            if (!n_clicks) return "";

            // Get the button that was clicked
            const buttonId = JSON.stringify(dash_clientside.callback_context.triggered[0].prop_id);
            // Extract the index from the button ID
            const match = buttonId.match(/\"index\":(\d+)/);
            if (!match) return "";

            const index = parseInt(match[1]);
            const errors = data.errors || [];

            if (index < errors.length) {
                const errorMsg = errors[index].error_msg || "";
                // Copy to clipboard
                navigator.clipboard.writeText(errorMsg).then(function() {
                    // Optionally show a tooltip or feedback
                    console.log("Copied to clipboard:", errorMsg.substring(0, 50) + "...");
                }).catch(function(err) {
                    console.error("Failed to copy:", err);
                    // Fallback: select the text for manual copying
                    const span = document.querySelector('[data-dash-component-id*="\\"type\\":\\"error-msg\\",\\"index\\":' + index + '"]');
                    if (span) {
                        const range = document.createRange();
                        range.selectNode(span);
                        window.getSelection().removeAllRanges();
                        window.getSelection().addRange(range);
                        document.execCommand('copy');
                        window.getSelection().removeAllRanges();
                    }
                });
            }

            return "";
        }
        """,
        Output("errors-store", "data", allow_duplicate=True),
        Input({"type": "btn-copy-error", "index": dash.dependencies.ALL}, "n_clicks"),
        State("errors-store", "data"),
        prevent_initial_call=True,
    )

